      - REDIS_URL=redis://redis:6379/0
    depends_on:
      - postgres
      - redis
    networks:
      - ios-network
    restart: unless-stopped

  # ========================================================================
  # PostgreSQL Database
  # ========================================================================
  postgres:
    image: postgres:15-alpine
    container_name: ios-postgres
    environment:
      - POSTGRES_DB=ios_db
      - POSTGRES_USER=ios_user
      - POSTGRES_PASSWORD=ios_password
    volumes:
      - postgres-data:/var/lib/postgresql/data
    networks:
      - ios-network
    restart: unless-stopped

  # ========================================================================
