  # ========================================================================
  redis:
    image: redis:7-alpine
    container_name: ios-redis
    volumes:
      - redis-data:/data
    networks:
      - ios-network
    restart: unless-stopped

  # ========================================================================
  # Nginx Reverse Proxy
  # ========================================================================
  nginx:
    image: nginx:alpine
    container_name: ios-nginx
    ports:
      - "80:80"
      - "443:443"
    volumes:
