    @task(1)
    def health_check(self):
        """
        Health check
        Weight: 1 (monitoring)
        """
        self.client.get(
            "/health",
            name="/health"
        )


class AdminUser(FastHttpUser):
    """
    Simulates admin user behavior
    Lower frequency, more resource-intensive operations
    """

    wait_time = between(5, 10)
    token = None

    def on_start(self):
