## 🔎 Search Implementation

### Elasticsearch Client

```python
# ios_core/search/elasticsearch_search.py

from typing import List, Dict, Optional
from elasticsearch import Elasticsearch
from elasticsearch.helpers import bulk
from dataclasses import dataclass
import logging

logger = logging.getLogger(__name__)

@dataclass
class SearchResult:
    """Individual search result"""
    document_id: int
    title: str
    summary: str
    score: float
    highlights: Dict[str, List[str]]
    metadata: Dict
    document_type: str

@dataclass
class SearchResponse:
    """Complete search response"""
    results: List[SearchResult]
    total_hits: int
    took_ms: int
    max_score: float
    aggregations: Optional[Dict] = None

class ElasticsearchSearchEngine:
    """
    Elasticsearch search implementation

    Features:
    - Multi-field search with boosting
    - Fuzzy matching
    - Phrase matching
    - Highlighting
    - Aggregations
    - Filtering
    - Pagination
    """

    def __init__(self, es_client: Elasticsearch, index_name: str = "documents"):
        self.es = es_client
        self.index_name = index_name

    def search(
        self,
        query: str,
        filters: Optional[Dict] = None,
        page: int = 1,
        page_size: int = 10,
        boost_fields: Optional[Dict[str, float]] = None,
        user_id: Optional[int] = None,
        fuzzy: bool = False,
        highlight: bool = True,
        aggregations: Optional[List[str]] = None
    ) -> SearchResponse:
        """
        Execute search query

        Args:
            query: Search query string
            filters: Structured filters (date, type, etc)
            page: Page number (1-indexed)
            page_size: Results per page
            boost_fields: Field boost values
            user_id: User ID for permission filtering
            fuzzy: Enable fuzzy matching
            highlight: Enable result highlighting
            aggregations: Fields to aggregate

        Returns:
            SearchResponse with results and metadata
        """
        # Build Elasticsearch query
        es_query = self._build_query(
            query=query,
            filters=filters,
            boost_fields=boost_fields,
            user_id=user_id,
            fuzzy=fuzzy
        )

        # Add highlighting
        if highlight:
            es_query["highlight"] = self._build_highlight_config()

        # Add aggregations
        if aggregations:
            es_query["aggs"] = self._build_aggregations(aggregations)

        # Pagination
        es_query["from"] = (page - 1) * page_size
        es_query["size"] = page_size

        # Execute search
        try:
            response = self.es.search(
                index=self.index_name,
                body=es_query,
                request_timeout=30
            )

            return self._parse_response(response)

        except Exception as e:
            logger.error(f"Elasticsearch search error: {e}")
            raise

    def _build_query(
        self,
        query: str,
        filters: Optional[Dict],
        boost_fields: Optional[Dict[str, float]],
        user_id: Optional[int],
        fuzzy: bool
    ) -> Dict:
        """
        Build Elasticsearch query DSL

        Query strategy:
        1. Multi-match across title, content, summary
        2. Apply field boosts
        3. Add filters (must clauses)
        4. Add permission filters
        5. Add fuzzy matching if enabled
        6. Boost recent documents
        """
        # Default boost values
        if not boost_fields:
            boost_fields = {
                'title': 2.0,
                'content': 1.0,
                'summary': 1.5,
                'tags': 1.3
            }

        # Build multi-match query
        must_clauses = []

        # Main search query
        multi_match = {
            "multi_match": {
                "query": query,
                "fields": [
                    f"title^{boost_fields.get('title', 2.0)}",
                    f"content^{boost_fields.get('content', 1.0)}",
                    f"summary^{boost_fields.get('summary', 1.5)}",
                    f"tags^{boost_fields.get('tags', 1.3)}"
                ],
                "type": "best_fields",
                "operator": "or",
                "minimum_should_match": "75%"
            }
        }

        if fuzzy:
            multi_match["multi_match"]["fuzziness"] = "AUTO"
            multi_match["multi_match"]["prefix_length"] = 2

        must_clauses.append(multi_match)

        # Phrase boost (exact phrase gets bonus)
        should_clauses = [
            {
                "match_phrase": {
                    "title": {
                        "query": query,
                        "boost": 3.0
                    }
                }
            },
            {
                "match_phrase": {
                    "content": {
                        "query": query,
                        "boost": 1.5
                    }
                }
            }
        ]

        # Build filter clauses
        filter_clauses = []

        # Permission filtering
        if user_id:
            filter_clauses.append(
                self._build_permission_filter(user_id)
            )

        # Structured filters
        if filters:
            if 'date_after' in filters:
                filter_clauses.append({
                    "range": {
                        "created_at": {
                            "gte": filters['date_after']
                        }
                    }
                })

            if 'date_before' in filters:
                filter_clauses.append({
                    "range": {
                        "created_at": {
                            "lte": filters['date_before']
                        }
                    }
                })

            if 'type' in filters:
                filter_clauses.append({
                    "term": {
                        "document_type": filters['type']
                    }
                })

            if 'tags' in filters:
                filter_clauses.append({
                    "terms": {
                        "tags": filters['tags']
                    }
                })

            if 'user' in filters:
                filter_clauses.append({
                    "term": {
                        "owner_id": filters['user']
                    }
                })

            if 'domain' in filters:
                filter_clauses.append({
                    "term": {
                        "domain": filters['domain']
                    }
                })

        # Active documents only
        filter_clauses.append({
            "term": {
                "status": "active"
            }
        })

        # Function score for recency boost
        function_score = {
            "function_score": {
                "query": {
                    "bool": {
                        "must": must_clauses,
                        "should": should_clauses,
                        "filter": filter_clauses,
                        "minimum_should_match": 1
                    }
                },
                "functions": [
                    {
                        "gauss": {
                            "created_at": {
                                "origin": "now",
                                "scale": "30d",
                                "decay": 0.5
                            }
                        },
                        "weight": 0.5
                    },
                    {
                        "field_value_factor": {
                            "field": "view_count",
                            "factor": 0.1,
                            "modifier": "log1p",
                            "missing": 0
                        },
                        "weight": 0.3
                    }
                ],
                "score_mode": "sum",
                "boost_mode": "multiply"
            }
        }

        return {
            "query": function_score,
            "track_total_hits": True
        }

    def _build_permission_filter(self, user_id: int) -> Dict:
        """
        Build permission filter

        User can see documents if:
        1. They own the document
        2. Document is public
        3. They have explicit permission
        """
        return {
            "bool": {
                "should": [
                    # Owner
                    {
                        "term": {
                            "owner_id": str(user_id)
                        }
                    },
                    # Public documents
                    {
                        "term": {
                            "metadata.visibility": "public"
                        }
                    },
                    # Explicit permission
                    {
                        "nested": {
                            "path": "permissions",
                            "query": {
                                "bool": {
                                    "must": [
                                        {
                                            "term": {
                                                "permissions.user_id": str(user_id)
                                            }
                                        },
                                        {
                                            "terms": {
                                                "permissions.access_level": ["read", "write", "admin"]
                                            }
                                        }
                                    ]
                                }
                            }
                        }
                    }
                ],
                "minimum_should_match": 1
            }
        }

    def _build_highlight_config(self) -> Dict:
        """Configure result highlighting"""
        return {
            "fields": {
                "title": {
                    "number_of_fragments": 0,
                    "pre_tags": ["<mark>"],
                    "post_tags": ["</mark>"]
                },
                "content": {
                    "fragment_size": 150,
                    "number_of_fragments": 3,
                    "pre_tags": ["<mark>"],
                    "post_tags": ["</mark>"]
                },
                "summary": {
                    "number_of_fragments": 1,
                    "pre_tags": ["<mark>"],
                    "post_tags": ["</mark>"]
                }
            },
            "require_field_match": False
        }

    def _build_aggregations(self, fields: List[str]) -> Dict:
        """Build aggregations for faceted search"""
        aggs = {}

        for field in fields:
            if field == "type":
                aggs["document_types"] = {
                    "terms": {
                        "field": "document_type",
                        "size": 20
                    }
                }
            elif field == "tags":
                aggs["tags"] = {
                    "terms": {
                        "field": "tags",
                        "size": 50
                    }
                }
            elif field == "date":
                aggs["date_histogram"] = {
                    "date_histogram": {
                        "field": "created_at",
                        "calendar_interval": "month",
                        "format": "yyyy-MM"
                    }
                }
            elif field == "owner":
                aggs["owners"] = {
                    "terms": {
                        "field": "owner_id",
                        "size": 20
                    }
                }
            elif field == "domain":
                aggs["domains"] = {
                    "terms": {
                        "field": "domain",
                        "size": 10
                    }
                }

        return aggs

    def _parse_response(self, response: Dict) -> SearchResponse:
        """Parse Elasticsearch response"""
        hits = response['hits']['hits']
        total_hits = response['hits']['total']['value']
        took_ms = response['took']
        max_score = response['hits']['max_score'] or 0.0

        results = []
        for hit in hits:
            source = hit['_source']
            highlights = hit.get('highlight', {})

            result = SearchResult(
                document_id=int(source['id']),
                title=source['title'],
                summary=source.get('summary', ''),
                score=hit['_score'],
                highlights=highlights,
                metadata={
                    'created_at': source.get('created_at'),
                    'owner_name': source.get('owner_name'),
                    'tags': source.get('tags', []),
                    'view_count': source.get('view_count', 0),
                    'file_extension': source.get('file_extension'),
                },
                document_type=source.get('document_type', 'unknown')
            )
            results.append(result)

        # Parse aggregations if present
        aggregations = None
        if 'aggregations' in response:
            aggregations = self._parse_aggregations(response['aggregations'])

        return SearchResponse(
            results=results,
            total_hits=total_hits,
            took_ms=took_ms,
            max_score=max_score,
            aggregations=aggregations
        )

    def _parse_aggregations(self, aggs: Dict) -> Dict:
        """Parse aggregation results"""
        parsed = {}

        for agg_name, agg_data in aggs.items():
            if 'buckets' in agg_data:
                parsed[agg_name] = [
                    {
                        'key': bucket['key'],
                        'count': bucket['doc_count']
                    }
                    for bucket in agg_data['buckets']
                ]

        return parsed

    def suggest(self, prefix: str, size: int = 10) -> List[str]:
        """
        Autocomplete suggestions

        Uses completion suggester on title field
        """
        try:
            response = self.es.search(
                index=self.index_name,
                body={
                    "suggest": {
                        "title-suggest": {
                            "prefix": prefix,
                            "completion": {
                                "field": "title.suggest",
                                "size": size,
                                "skip_duplicates": True
                            }
                        }
                    }
                }
            )

            suggestions = []
            for option in response['suggest']['title-suggest'][0]['options']:
                suggestions.append(option['text'])

            return suggestions

        except Exception as e:
            logger.error(f"Suggest error: {e}")
            return []

    def more_like_this(
        self,
        document_id: int,
        size: int = 10
    ) -> List[SearchResult]:
        """
        Find similar documents using More Like This query

        Uses term frequency analysis to find similar documents
        """
        try:
            response = self.es.search(
                index=self.index_name,
                body={
                    "query": {
                        "more_like_this": {
                            "fields": ["title", "content", "tags"],
                            "like": [
                                {
                                    "_index": self.index_name,
                                    "_id": str(document_id)
                                }
                            ],
                            "min_term_freq": 2,
                            "max_query_terms": 25,
                            "min_doc_freq": 5,
                            "minimum_should_match": "30%"
                        }
                    },
                    "size": size
                }
            )

            return self._parse_response(response).results

        except Exception as e:
            logger.error(f"More like this error: {e}")
